package com.example.hotel;
import static org.assertj.core.api.Assertions.assertThat; import com.alibaba.cola.statemachine.*; import com.example.hotel.config.*; import com.example.hotel.domain.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest;
@SpringBootTest class OrderStateMachineTest{@Autowired OrderStateMachineConfig config;@Test void onlyBookedCanCheckIn(){StateMachine<OrderStatus,OrderEvent,Object> machine=StateMachineFactory.get(OrderStateMachineConfig.MACHINE_ID);assertThat(machine.fireEvent(OrderStatus.BOOKED,OrderEvent.CHECK_IN,null)).isEqualTo(OrderStatus.CHECKED_IN);assertThat(machine.fireEvent(OrderStatus.CHECKED_IN,OrderEvent.CHECK_IN,null)).isEqualTo(OrderStatus.CHECKED_IN);}}
